#include <stdio.h>
#include <stdlib.h>

#define MAX_STACK_SIZE 100

int stack[MAX_STACK_SIZE];
int top = 0;

void push(int value) {
    if (top < MAX_STACK_SIZE) {
        stack[top++] = value;
    } else {
        printf("ERROR: Stack overflow\n");
        exit(1);
    }
}

int pop() {
    if (top > 0) {
        return stack[--top];
    } else {
        printf("ERROR: Stack underflow\n");
        exit(1);
    }
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("ERROR: Not enough arguments\n");
        return 1;
    }

    for (int i = 1; i < argc; i++) {
        char *arg = argv[i];
        if (arg[0] == '+') {
            if (top < 2) {
                printf("ERROR: Not enough operands for +\n");
                return 1;
            }
            int b = pop();
            int a = pop();
            push(a + b);
        } else if (arg[0] == '-') {
            if (top < 2) {
                printf("ERROR: Not enough operands for -\n");
                return 1;
            }
            int b = pop();
            int a = pop();
            push(a - b);
        } else if (arg[0] == '*') {
            if (top < 2) {
                printf("ERROR: Not enough operands for *\n");
                return 1;
            }
            int b = pop();
            int a = pop();
            push(a * b);
        } else if (arg[0] == '/') {
            if (top < 2) {
                printf("ERROR: Not enough operands for /\n");
                return 1;
            }
            int b = pop();
            int a = pop();
            if (b == 0) {
                printf("ERROR: Division by zero\n");
                return 1;
            }
            push(a / b);
        } else {
            int value = atoi(arg);
            push(value);
        }
    }

    if (top != 1) {
        printf("ERROR: Invalid expression\n");
        return 1;
    }

    printf("%d\n", pop());
    return 0;
}
